import os, glob, re

def load_state():
    d = os.path.normpath(os.environ.get('RLM_SESSION_DIR', ''))
    if not d:
        return {}
    session_file = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'
    G = {}
    try:
        content = open(session_file).read()
        for match in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content):
            k, h, w = match[1], int(match[2]), int(match[3])
            lines = []
            start = match.end()
            for i in range(h * w):  # Each cell per line for demos
                pass
            # Try to extract grid rows
            after = content[match.end():]
            # Find the next "input" or "output" marker
            rest = after[:h * w]  # approximate
            rows = []
            in_grid = True
            i = 0
            while in_grid and len(rows) < h and i < len(after):
                line = after[i:(i+1000)]
                if 'input' in line.lower() or 'output' in line.lower():
                    in_grid = False
                elif line.strip().startswith('[') or line.strip().startswith('5'):
                    rows.append(list(map(int, line.strip().split())))
                elif rows:
                    break
                elif line.strip() != '':
                    # Check if it might be start of next
                    if line.strip().startswith('['):
                        if len(rows) < h:
                            rows[-1] = [int(x) for x in line.strip().split()]
                        elif len(rows[-1]) == w:
                            rows.append(list(map(int, line.strip().split())))
                i += 1
            if rows and len(rows) == h and all(len(r) == w for r in rows):
                G[k] = rows
    except Exception as e:
        print(f"Error: {e}")
    return G

G = load_state()
print("Loaded grids:", sorted(G.keys()))
for k, v in G.items():
    print(f"{k}: {len(v)}x{len(v[0]) if v else 0}")

